import fc from 'fast-check';

/** Dates generated by the JS Date object, so they are independent of the engine under test. */
export const isoDateArb = fc
  .date({
    min: new Date('1900-01-01T00:00:00.000Z'),
    max: new Date('2199-12-31T00:00:00.000Z'),
    noInvalidDate: true,
  })
  .map((d) => d.toISOString().slice(0, 10));

/** Dates in the range real contracts live in. Keeps multi-decade arithmetic inside the supported years. */
export const contractDateArb = fc
  .date({
    min: new Date('1990-01-01T00:00:00.000Z'),
    max: new Date('2060-12-31T00:00:00.000Z'),
    noInvalidDate: true,
  })
  .map((d) => d.toISOString().slice(0, 10));
